import os, openpyxl, docx, pypdf

def check_file(path):
    text = ''
    try:
        if path.endswith('.pdf'):
            reader = pypdf.PdfReader(path)
            text = ' '.join(page.extract_text() or '' for page in reader.pages)
        elif path.endswith('.docx'):
            doc = docx.Document(path)
            text = ' '.join(p.text for p in doc.paragraphs)
            for t in doc.tables:
                for row in t.rows:
                    for cell in row.cells:
                        text += ' ' + cell.text
        elif path.endswith('.xlsx'):
            wb = openpyxl.load_workbook(path, data_only=True)
            for s in wb.sheetnames:
                for row in wb[s].iter_rows(values_only=True):
                    text += ' ' + ' '.join(str(v) for v in row if v is not None)
        elif path.endswith(('.txt', '.eml')):
            with open(path, 'r', errors='ignore') as f:
                text = f.read()
    except Exception as e:
        pass
    return text

for root, dirs, files in os.walk('.'):
    for f in sorted(files):
        p = os.path.join(root, f)
        t = check_file(p)
        for term in ['Halbray', 'PXA-2024-0002', 'ALN-159']:
            if term.lower() in t.lower():
                print(f'{p} matches {term}')
